SCENARIO("an account with a balance", "[account]") {
    GIVEN("an account with 100") {
        Account acct(100);
        WHEN("30 is withdrawn") {
            const auto ok = acct.withdraw(30);
            THEN("the balance is 70") {
                REQUIRE(ok);
                REQUIRE(acct.balance() == 70);
            }
        }
    }
}

