class AccountTest : public ::testing::Test {
 protected:
  void SetUp() override { account_.deposit(100); }   // Arrange
  Account account_;
};

TEST_F(AccountTest, WithdrawWithinBalanceReducesBalance) {
  const bool ok = account_.withdraw(30);             // Act
  EXPECT_TRUE(ok);                                   // Assert
  EXPECT_EQ(70, account_.balance());
}
